function renderTable(rows) {
  if (rows.length === 0)
    return "";
  const colCount = rows[0].length;
  const widths = [];
  for (let i = 0;i < colCount; i++) {
    let max = 0;
    for (const row of rows) {
      const cellLen = String(row[i] ?? "").length;
      if (cellLen > max)
        max = cellLen;
    }
    widths.push(max);
  }
  const lines = [];
  for (const row of rows) {
    const padded = row.map((cell, i) => {
      const s = String(cell ?? "");
      return s + " ".repeat(widths[i] - s.length);
    });
    lines.push(padded.join("  "));
  }
  return lines.join(`
`);
}
function canonicalJsonForTable(value) {
  if (Array.isArray(value)) {
    return "[" + value.map(canonicalJsonForTable).join(",") + "]";
  }
  if (value !== null && typeof value === "object") {
    const obj = value;
    const keys = Object.keys(obj).sort();
    return "{" + keys.map((k) => JSON.stringify(k) + ":" + canonicalJsonForTable(obj[k])).join(",") + "}";
  }
  return JSON.stringify(value);
}
function renderTwoColumn(payload, columns) {
  const rows = [["FIELD", "VALUE"]];
  for (const key of columns) {
    let cell;
    if (key in payload) {
      const value = payload[key];
      if (value === null || value === undefined) {
        cell = "-";
      } else if (typeof value === "object") {
        cell = canonicalJsonForTable(value);
      } else {
        cell = String(value);
      }
    } else {
      cell = "-";
    }
    rows.push([key, cell]);
  }
  return renderTable(rows);
}

